/** Counts discarded sorting and encoding work rather than relying on wall-clock timing. */
class LmdbPersistentAdjacencyBulkWorkTest {

	@TempDir
	Path directory;

	@Test
	void alignedWritesDoNotRequestUnusedPermutationKeys() throws Exception {
		AtomicInteger preparations = new AtomicInteger();
		Set<List<Long>> expected = Set.of(List.of(10L, 20L, 30L, 0L), List.of(11L, 20L, 31L, 7L),
				List.of(12L, 20L, 32L, 7L), List.of(13L, 20L, 33L, 0L));
		Set<List<Long>> inferred = Set.of(List.of(99L, 20L, 999L, 9L));
		LmdbStoreConfig config = config("spoc,posc,cspo");
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			store.startTransaction();
			store.storeTriple(10, 20, 30, 0, true);
			store.storeTriple(11, 20, 31, 7, false);
			store.storeTriple(99, 20, 999, 9, false);
			store.commit();

			long[] subjects = { 12, 10, 11, 12, 13 };
			long[] predicates = { 20, 20, 20, 20, 20 };
			long[] objects = { 32, 30, 31, 32, 33 };
			long[] contexts = { 7, 0, 7, 7, 0 };
			List<Integer> added = new ArrayList<>();
			store.startTransaction();
			// A false advisory hint must still promote the existing inferred row and retain its control row.
			store.storePreparedTriples(subjects, predicates, objects, contexts, subjects.length, true, false,
					added::add, null, () -> {
						preparations.incrementAndGet();
						return store.prepareSecondaryIndexes(subjects, predicates, objects, contexts, subjects.length);
					});
			assertThat(added).containsExactly(0, 2, 4);
			try (RecordIterator rows = store.getTriplesForWrite(-1, -1, -1, -1, true)) {
				assertThat(readRows(rows)).isEqualTo(expected);
			}
			store.commit();
			assertDirections(store, expected, true);
			assertDirections(store, inferred, false);
		}
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			assertDirections(store, expected, true);
			assertDirections(store, inferred, false);
		}
		assertThat(preparations.get()).as("adjacency insertion consumes quads, never permutation-key arenas")
				.isZero();
	}

	@Test
	void initialRunImportSortsBothConsumedDirections() throws Exception {
		AtomicInteger sorts = new AtomicInteger();
		Set<List<Long>> expected = Set.of(List.of(10L, 20L, 30L, 0L), List.of(11L, 21L, 31L, 7L),
				List.of(12L, 20L, 32L, 7L), List.of(13L, 21L, 33L, 0L));
		LmdbStoreConfig config = config("cspo,spco,spoc,posc");
		Path triples = directory.resolve("triples");
		Path runs = Files.createDirectory(directory.resolve("runs"));
		int runOrders;
		try (TripleStore store = new TripleStore(triples.toFile(), config, null);
				LmdbRunCollector collector = new LmdbRunCollector("adjacency", runs, store.initialImportFieldOrders(),
						32, 1, task -> {
							sorts.incrementAndGet();
							task.run();
						})) {
			for (long[] quad : new long[][] { { 13, 21, 33, 0 }, { 10, 20, 30, 0 }, { 12, 20, 32, 7 },
					{ 11, 21, 31, 7 }, { 12, 20, 32, 7 }, { 10, 20, 30, 0 } }) {
				collector.add(quad[0], quad[1], quad[2], quad[3]);
			}
			collector.commit();
			List<LmdbSortedRuns.Runs> prepared = collector.completeRuns();
			runOrders = prepared.size();
			store.startTransaction();
			assertThat(store.appendInitialImportRuns(prepared, 1L << 20, runs)).isEqualTo(expected.size());
			store.commit();
			assertDirections(store, expected, true);
		}
		try (TripleStore store = new TripleStore(triples.toFile(), config, null)) {
			assertDirections(store, expected, true);
		}
		assertThat(sorts.get()).as("one sort per physical direction despite additional logical query orders")
				.isEqualTo(2);
		assertThat(runOrders).as("both consumed canonical directions are materialized").isEqualTo(2);
	}

	@ParameterizedTest
	@ValueSource(strings = { "spoc,posc", "cspo,spco,spoc,posc" })
	void preparedRepositoryBatchDoesNotCreateDiscardedPermutationWork(String orders) throws Exception {
		var values = SimpleValueFactory.getInstance();
		Model expected = new LinkedHashModel();
		for (int row = 0; row < 2048; row++) {
			expected.add(values.createIRI("urn:adjacency-work:s:" + row),
					values.createIRI("urn:adjacency-work:p:" + row % 4), values.createLiteral("object " + row),
					row % 2 == 0 ? null : values.createIRI("urn:adjacency-work:g:" + row % 3));
		}
		List<Statement> input = new ArrayList<>(expected);
		input.addAll(input.subList(0, 256));
		LmdbStoreConfig config = config(orders).setInitialRunImportEnabled(false);
		CountingStore store = new CountingStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin(IsolationLevels.READ_COMMITTED);
				connection.add(input);
				connection.commit();
				assertRepositoryRows(connection, expected);
			}
		} finally {
			repository.shutDown();
		}
		SailRepository reopened = new SailRepository(new LmdbStore(directory.toFile(), config));
		try {
			reopened.init();
			try (RepositoryConnection connection = reopened.getConnection()) {
				assertRepositoryRows(connection, expected);
			}
		} finally {
			reopened.shutDown();
		}
		assertThat(store.preparations.get())
				.as("the real prepared ingestion path must not sort or encode unused statement permutations")
				.isZero();
	}

	private static void assertDirections(TripleStore store, Set<List<Long>> expected, boolean explicit)
			throws IOException {
		store.getTxnManager().doWith((stack, txn) -> {
			LmdbPersistentAdjacency adjacency = LmdbPersistentAdjacency.openExisting(txn);
			for (boolean incoming : new boolean[] { false, true }) {
				try (RecordIterator rows = adjacency.scan(txn, -1, -1, -1, -1, explicit, incoming)) {
					assertThat(readRows(rows)).isEqualTo(expected);
				}
			}
			assertThat(adjacency.count(txn, explicit)).isEqualTo(expected.size());
			return null;
		});
	}

	private static Set<List<Long>> readRows(RecordIterator rows) throws IOException {
		Set<List<Long>> result = new HashSet<>();
		for (long[] quad; (quad = rows.next()) != null;) {
			assertThat(result.add(List.of(quad[0], quad[1], quad[2], quad[3]))).isTrue();
		}
		return result;
	}

	private static void assertRepositoryRows(RepositoryConnection connection, Model expected) {
		Model actual = new LinkedHashModel();
		try (var rows = connection.getStatements(null, null, null, false)) {
			while (rows.hasNext()) {
				assertThat(actual.add(rows.next())).isTrue();
			}
		}
		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(connection.size()).isEqualTo(expected.size());
	}

	private static LmdbStoreConfig config(String orders) {
		return new LmdbStoreConfig(orders).setBulkOperationSize(4096)
				.setSketchEstimatorEnabled(false)
				.setAutoGrow(false)
				.setForceSync(true)
				.setTripleDBSize(64L << 20)
				.setValueDBSize(64L << 20);
	}

	private static final class CountingStore extends LmdbStore {
		private final AtomicInteger preparations = new AtomicInteger();

		private CountingStore(File directory, LmdbStoreConfig config) {
			super(directory, config);
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException {
			return new LmdbSailStore(directory, properties, config, sketches, ValueStore::new,
					(triples, metadata, settings, dictionary) -> new TripleStore(triples, metadata, settings,
							dictionary) {
						@Override
						PreparedSecondaryIndexes prepareSecondaryIndexes(long[] subjects, long[] predicates,
								long[] objects, long[] contexts, int count) {
							preparations.incrementAndGet();
							return super.prepareSecondaryIndexes(subjects, predicates, objects, contexts, count);
						}

						@Override
						PreparedSecondaryIndexesTask prepareSecondaryIndexesAsync(ExecutorService executor,
								long[] subjects, long[] predicates, long[] objects, long[] contexts, int count) {
							preparations.incrementAndGet();
							return super.prepareSecondaryIndexesAsync(executor, subjects, predicates, objects, contexts,
									count);
						}
					});
		}
	}
}
